describe('Skip to Content Link Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should navigate to the main content when the skip-to-content link is clicked', () => {
        cy.get('a.skip-to-content') // Replace with the actual selector for the skip-to-content link
            .should('be.visible')
            .click();

        cy.url().should('include', '#main-content'); // Replace with the actual ID or selector of the main content
        cy.get('#main-content').should('be.visible'); // Ensure the main content is visible
    });

    it('should not navigate if the skip-to-content link is not present', () => {
        cy.get('a.skip-to-content').should('exist'); // Check if the link exists
        cy.get('a.skip-to-content').click();

        cy.url().should('include', '#main-content'); // Ensure the URL includes the main content anchor
        cy.get('#main-content').should('be.visible'); // Ensure the main content is visible
    });
});
